from pathlib import Path
import json,hashlib,datetime,subprocess
H=Path(__file__).resolve().parent
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
d=json.loads((H/'story-data.json').read_text());metrics=json.loads((H/'metrics.json').read_text());htmlsha=sha(H/'white-fang.html');datasha=sha(H/'story-data.json')
reports={}
for phase in ['320','390','1024','1440','consent','entries','ios','tails','controls']:
 p=H/'qa'/f'browser-{phase}.json';r=json.loads(p.read_text())
 assert r['status']=='completed' and r['profileRemoved'] and r['processGroupTerminated'],phase
 assert not r['runtimeErrors'] and not r['remoteRequests'],phase
 assert r['inputHashes']['white-fang.html']==htmlsha and r['inputHashes']['story-data.json']==datasha,phase
 reports[phase]={'file':str(p),'sha256':sha(p),'status':r['status']}
audit=json.loads((H/'qa'/'audit-final.json').read_text());assert audit['passes']==69 and not audit['warnings'] and not audit['failures']
for f,expected in json.loads((H/'build-record.json').read_text())['installedHashes'].items():assert sha(Path('/Users/pn/.codex/skills/book-tiktok')/f)==expected
source=json.loads((H/'source-coverage.json').read_text());assert sha(Path(source['source']))==source['sourceSha256'];assert len(source['chaptersRead'])==25 and all(x['readComplete'] for x in source['chaptersRead'])
rows=subprocess.run(['ps','-axo','pid=,args='],capture_output=True,text=True,check=True).stdout.splitlines()
remaining=[]
for row in rows:
 parts=row.strip().split(None,1)
 if len(parts)==2 and parts[1].startswith('/Applications/Google Chrome.app/') and 'white-fang-depth-v2-' in parts[1]:remaining.append(row.strip())
assert not remaining,remaining
assert not list(Path('/private/tmp').glob('white-fang-depth-v2-*'))
cleanup=H/'qa'/'cleanup.json';r=json.loads(cleanup.read_text());r['allOwnedChromeAndHelperCommandsRemaining']=remaining;r['verifiedAtUtc']=datetime.datetime.now(datetime.timezone.utc).isoformat();cleanup.write_text(json.dumps(r,indent=2)+'\n')
# Every reviewable file except this self-referential manifest is bound; the primary itself is not copied.
files={str(p.relative_to(H)):{'path':str(p),'sha256':sha(p),'bytes':p.stat().st_size} for p in sorted(H.rglob('*')) if p.is_file() and p.name!='ready.json'}
ready={'schemaVersion':2,'slug':'white-fang','title':{'ru':'Белый Клык','en':'White Fang'},'author':'Jack London','candidate':'depth-v2','preparedAtUtc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'ready-for-root-personal-check','publicationAllowed':False,'bookContentPublicationAllowed':False,'rootPersonalAcceptance':False,'rootReviewRequired':True,'rootRequiredReadScope':{'completeFinalRuEnProse':False,'allThreeRoutesBothLanguages':False,'framingSourcesAndEndingGates':False,'chapterSceneMapAndOmissions':False,'keyPrimaryMechanisms':False,'exactHashBoundPersonalRecord':False},'ownership':{'onlyDirectoryWritten':str(H),'oldCollectorReadyReviewsUntouchedByThisImplementation':True,'rootReaderCatalogueGlobalLedgerUntouchedByThisImplementation':True,'installedSharedFilesReadOnly':True,'otherCandidatesUntouched':True,'subagentsStarted':0,'gitPrDeployActions':0,'published':False},'deliverables':{name:files[name] for name in ['draft-ru.md','draft-en.md','story-data.json','white-fang.html','chapter-scene-map.md','scene-map.json','sources.md','reading-ledger.md','source-coverage.json','reading-ranges.jsonl','primary-checks.json','metrics.json','QA.md','implementation-review.md']},'routeFiles':{m:{l:files[f'routes/{m}-{l}.md'] for l in ['ru','en']} for m in ['essential','core','deep']},'counts':d['targetModes'],'narrativeParagraphPairs':85,'narrativeMode':True,'defaults':{'language':'ru','theme':'dark','depth':'essential','readingFont':'sans'},'metrics':metrics,'source':{'count':1,'primaryWitness':source['source'],'sha256':source['sourceSha256'],'partsRead':5,'completeChaptersRead':25,'workLines':[83,7519],'consecutiveReadRanges':len(source['ranges']),'sourceGaps':[],'notClaimed':['Published Russian translation verification','Print-edition collation','Root personal acceptance']},'lengthReason':'85 sustained original narrative paragraphs across all25 chapters, with developed siege, cub encounters, camp/separation, repeated sale/escape, Cherokee, slow Scott relationship, southern scenes and complete ending. Actual omissions are mapped. 8,123RU words is an outcome of coverage, not a quota.','spoilerPolicy':{'kind':'full-plot-in-deep','shortRouteStop':'iv-3-p3: Cherokee appears; no outcome','deepWarning':'deep-warning','actualLastNarrative':'v-5-p6: puppies and sunlight','consent':'volatile in-memory document session; revoked on lowering depth and document replacement/BFCache restore','progressNamespace':'book-tiktok.white-fang.depth-v2.','oldProgressMigrated':False,'globalPreferencesPreserved':True},'qa':{'structuralAudit':{'passes':69,'warnings':0,'failures':0,'file':'qa/audit-final.json'},'actualDraftDataHtmlParagraphParity':True,'allFinalHashReports':reports,'renderedMatrixScreenInstances':sum(json.loads((H/'qa'/f'browser-{p}.json').read_text())['renderedInstances'] for p in ['320','390','1024','1440']),'actualLastCharacterChecks':json.loads((H/'qa'/'browser-tails.json').read_text())['lastCharactersVerified'],'savedDeepEntryChecks':json.loads((H/'qa'/'browser-consent.json').read_text())['savedDeep']['paths'],'physicalSafariTested':False,'contentServerStarted':False,'allOwnedChromeCleaned':True},'remaining':['Root must personally read all final RU/EN prose and routes, compare omissions/coverage and key primary passages, and record a decision bound to these hashes. No publication until that acceptance.','Chrome desktop/mobile and iOS-mode emulation only; no physical Safari/PWA certification.'],'allArtifactHashes':files}
(H/'ready.json').write_text(json.dumps(ready,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'status':ready['status'],'counts':ready['counts'],'narrativeWords':metrics['depths']['deep']['narrativeWords'],'htmlSha256':htmlsha,'jsonSha256':datasha,'artifactFilesBound':len(files),'publicationAllowed':False,'rootPersonalAcceptance':False},ensure_ascii=False,indent=2))
